updates.replace:
.btn--card-type {
    flex-direction: row;
    justify-content: flex-start;
    min-width: 100%;
    max-width: none;
    gap: 8px;
    padding: 14px 16px;
    min-height: 48px;
    align-items: center;
}

.btn--card-type .material-icons {
    margin-bottom: 0;
    margin-right: 8px;
    font-size: 20px;
}

.btn--card-type span:last-child {
    font-size: 0.95rem;
    flex: 1;
    text-align: left;
}

updates.append:
/* Additional mobile spacing fix */
@media (max-width: 768px) {
    /* Ensure cards after management cards have proper spacing */
    .management-card + .card,
    .management-card + .new-card {
        margin-top: 15px;
    }

    /* Extra bottom padding for filter input group */
    .management-card .filter-input-group {
        margin-bottom: 15px !important;
    }
}
